package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeAggregateCompiler.memoReadMask;

import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;

/**
 * Prices a native plan as the executor that will run it works, node kind by node kind, where the generic chain
 * ({@link LmdbNativeCostVectors#plan}) sees only a probe chain:
 * <ul>
 * <li>a FILTER's EXISTS witness: one membership probe per row for a single pattern, a first match of the subplan per
 * distinct key when its read set is known (memoised) plus a memo lookup per row, else the subplan per row;</li>
 * <li>MINUS by {@code MinusCursor}'s gates: the right side once when nothing is shared, a membership probe per left row
 * for a single pattern, a correlated first match per key when the right side assures the shared slots, and otherwise
 * the whole right side per key or per left row (the uncorrelated case);</li>
 * <li>OPTIONAL: a payload probe per left row for a pattern right side, a memoised fragment per key with its rows
 * replayed per left row when the right memo applies, else the right side per left row;</li>
 * <li>a multi-join's filters at the depth they are placed, with their witnesses;</li>
 * <li>a sequential island (subquery, generic evaluation, path, graph, tuple function) from its own work estimate, once
 * when it is not correlated with the prefix (its rows are replayed per prefix row), per prefix row otherwise, and the
 * store sweep only where nothing is known.</li>
 * </ul>
 * {@link Mode#BATCH} charges a batch row per produced row and, where the batch cursor falls back to a row cursor
 * (MINUS, OPTIONAL, an unplannable filter), an interpreted row plus a batch row per converted row. {@link Mode#KERNEL}
 * prices EXISTS and MINUS bodies the lowering accepts as witnesses: one seek per pattern and one record per outer row,
 * with no cursor open, memo or membership structure; OPTIONAL as a correlated probe per left row; anything the lowering
 * hands to a native operator at the sequential charge.
 */
final class LmdbNativePlanExecutionProfile {

	enum Mode {
		SEQUENTIAL,
		BATCH,
		KERNEL
	}

	private final RowState row;
	private final Mode mode;

	private LmdbNativePlanExecutionProfile(RowState row, Mode mode) {
		this.row = row;
		this.mode = mode;
	}

	/**
	 * The generic cursor chain's row against an interpreted kernel row: fitted 2026-11-03 on the 3000-person regret
	 * harness (runs j and k, physical prices pinned) at 200 to 435 ns against 118 to 126 ns. The user's rule for
	 * {@code nestedLoop}: the honest price plus a measured premium for the path with the fewest optimisations.
	 */
	static final double GENERIC_ROW_PREMIUM = 1.65D;

	static LmdbNativeCostVector profile(SlotPlan plan, RowState row, long boundMask, Mode mode) {
		LmdbNativeCostVector priced = new LmdbNativePlanExecutionProfile(row, mode).price(plan, boundMask);
		return mode == Mode.SEQUENTIAL ? withPremium(priced) : priced;
	}

	/** Every interpreted row of the generic chain at the premium. */
	private static LmdbNativeCostVector withPremium(LmdbNativeCostVector vector) {
		if (vector.high(Feature.INTERPRETED_ROW) <= 0D) {
			return vector;
		}
		LmdbNativeCostVector.Builder builder = LmdbNativeCostVector.builder();
		for (Feature feature : Feature.values()) {
			if (vector.high(feature) <= 0D) {
				continue;
			}
			double factor = feature == Feature.INTERPRETED_ROW ? GENERIC_ROW_PREMIUM : 1D;
			builder.add(feature, vector.low(feature) * factor, vector.expected(feature) * factor,
					vector.high(feature) * factor);
		}
		return builder.build();
	}

	/**
	 * The kernel's streaming vector: the plan in kernel form, with the interpreted tier's per-row feature in place of
	 * the compiled tier's generated row.
	 */
	static LmdbNativeCostVector kernelVector(SlotPlan plan, RowState row, long boundMask, Feature rowFeature) {
		LmdbNativeCostVector kernel = profile(plan, row, boundMask, Mode.KERNEL);
		if (rowFeature == Feature.GENERATED_ROW) {
			return kernel;
		}
		LmdbNativeCostVector.Builder builder = LmdbNativeCostVector.builder();
		for (Feature feature : Feature.values()) {
			if (kernel.high(feature) > 0D) {
				builder.add(feature == Feature.GENERATED_ROW ? rowFeature : feature, kernel.low(feature),
						kernel.expected(feature), kernel.high(feature));
			}
		}
		return builder.build();
	}

	/** Whether the plan has a body (EXISTS, MINUS, OPTIONAL, island) the generic chain prices as a probe chain. */
	static boolean hasCorrelatedBody(SlotPlan plan) {
		if (plan instanceof FilterPlan filter) {
			return witnessOf(filter.filter) || hasCorrelatedBody(filter.arg);
		}
		if (plan instanceof MinusPlan || plan instanceof LeftJoinPlan || isIsland(plan)) {
			return true;
		}
		if (plan instanceof JoinPlan join) {
			return hasCorrelatedBody(join.left) || hasCorrelatedBody(join.right);
		}
		if (plan instanceof MultiJoinPlan multiJoin) {
			for (MaskedFilter filter : multiJoin.filters) {
				if (witnessOf(filter.filter)) {
					return true;
				}
			}
			for (SlotPlan child : multiJoin.children) {
				if (hasCorrelatedBody(child)) {
					return true;
				}
			}
			return false;
		}
		if (plan instanceof UnionPlan union) {
			return hasCorrelatedBody(union.left) || hasCorrelatedBody(union.right);
		}
		if (plan instanceof ExtensionPlan extension) {
			return hasCorrelatedBody(extension.arg);
		}
		if (plan instanceof RowDistinctPlan distinct) {
			return hasCorrelatedBody(distinct.arg);
		}
		return false;
	}

	private static boolean witnessOf(NativeBooleanFilter filter) {
		if (filter instanceof RecordingNativeBooleanFilter recording) {
			return witnessOf(recording.delegate);
		}
		if (filter instanceof NegatedNativeBooleanFilter negated) {
			return witnessOf(negated.delegate);
		}
		if (filter instanceof BooleanCombinationFilter combination) {
			return witnessOf(combination.left) || witnessOf(combination.right);
		}
		return filter instanceof StatementPatternExistsFilter || filter instanceof ExistsFilter;
	}

	static boolean isIsland(SlotPlan plan) {
		return plan instanceof NativeSubqueryPlan || plan instanceof GenericEvalPlan || plan instanceof NativeGraphPlan
				|| plan instanceof PathPlan || plan instanceof TupleFunctionPlan;
	}

	private Feature rowFeature() {
		return mode == Mode.BATCH ? Feature.BATCH_ROW
				: mode == Mode.KERNEL ? Feature.GENERATED_ROW : Feature.INTERPRETED_ROW;
	}

	private double rows(SlotPlan plan, long mask) {
		return LmdbNativeCostVectors.rows(plan, row, mask);
	}

	private LmdbNativeCostVector perRow(Feature feature, double count) {
		return LmdbNativeCostVectors.perRow(feature, count, row);
	}

	private LmdbNativeCostVector sweep() {
		return LmdbNativeCostVectors.sweep(row, rowFeature());
	}

	LmdbNativeCostVector price(SlotPlan plan, long mask) {
		if (plan instanceof FilterPlan filter) {
			double rows = rows(filter.arg, mask);
			return price(filter.arg, mask).plus(perRow(Feature.INTERPRETED_ROW, rows))
					.plus(witness(filter.filter, rows, mask | filter.arg.producedMask()));
		}
		if (plan instanceof MinusPlan minus) {
			return minus(minus, mask);
		}
		if (plan instanceof LeftJoinPlan leftJoin) {
			return leftJoin(leftJoin, mask);
		}
		if (plan instanceof JoinPlan join) {
			return repeated(price(join.left, mask), join.left, join.right, mask);
		}
		if (plan instanceof LateralPlan lateral) {
			return repeated(price(lateral.left, mask), lateral.left, lateral.right, mask);
		}
		if (plan instanceof MultiJoinPlan multiJoin) {
			return multiJoin(multiJoin, mask);
		}
		if (plan instanceof UnionPlan union) {
			return price(union.left, mask).plus(price(union.right, mask));
		}
		if (plan instanceof ExtensionPlan extension) {
			double rows = rows(extension.arg, mask);
			return price(extension.arg, mask)
					.plus(perRow(Feature.INTERPRETED_ROW, multiply(rows, extension.copies.length)));
		}
		if (plan instanceof RowDistinctPlan distinct) {
			return price(distinct.arg, mask).plus(perRow(Feature.MEMBERSHIP_TEST, rows(distinct.arg, mask)));
		}
		if (plan instanceof NativeAliasJoinPlan alias) {
			return price(alias.original, mask);
		}
		if (plan instanceof NativeAliasJoinMemoPlan memo) {
			return price(memo.original, mask);
		}
		if (isIsland(plan)) {
			return island(plan, mask);
		}
		return LmdbNativeCostVectors.plan(plan, row, mask, rowFeature());
	}

	/** An island's own work estimate, or the sweep where it has none. */
	private LmdbNativeCostVector island(SlotPlan plan, long mask) {
		LmdbNativeWork work = plan.estimateWork(row, mask);
		return work.known()
				? LmdbNativeCostVector.bounds(Feature.SCANNED_ROW, work.low(), (work.low() + work.high()) / 2D,
						work.high())
				: sweep();
	}

	/**
	 * Whether a child's evaluation depends on slots the prefix binds: true when its read set names one of them, and for
	 * a plan whose read set is unknown, when any slot beyond the entry row is bound at all.
	 */
	private boolean correlated(SlotPlan plan, long mask) {
		long readMask = memoReadMask(plan);
		long prefixBound = mask & ~row.boundMask();
		return readMask < 0L ? prefixBound != 0L : (readMask & prefixBound) != 0L;
	}

	/** {@code left} once, then {@code right} once per left row (or once with its rows replayed when uncorrelated). */
	private LmdbNativeCostVector repeated(LmdbNativeCostVector left, SlotPlan leftPlan, SlotPlan right, long mask) {
		double leftRows = rows(leftPlan, mask);
		if (Double.isNaN(leftRows)) {
			return left.plus(sweep());
		}
		return left.plus(child(right, mask | leftPlan.producedMask(), leftRows));
	}

	/** A child entered {@code prefixRows} times: per prefix row, unless it is an island the prefix does not reach. */
	private LmdbNativeCostVector child(SlotPlan plan, long mask, double prefixRows) {
		if (isIsland(plan) && !correlated(plan, mask)) {
			double replayed = rows(plan, mask);
			return island(plan, mask).plus(perRow(Feature.DECODED_ROW, multiply(replayed, prefixRows)));
		}
		return price(plan, mask).scale(prefixRows);
	}

	private LmdbNativeCostVector multiJoin(MultiJoinPlan multiJoin, long boundMask) {
		MultiJoinPlan.OrderedPlan ordered = multiJoin.derivedPlan(boundMask);
		LmdbNativeCostVector total = LmdbNativeCostVector.zero();
		double prefixRows = 1D;
		long mask = boundMask;
		for (int i = 0; i < ordered.order.length; i++) {
			SlotPlan child = ordered.order[i];
			total = total.plus(child(child, mask, prefixRows));
			double childRows = rows(child, mask);
			if (Double.isNaN(childRows)) {
				for (int j = i + 1; j < ordered.order.length; j++) {
					total = total.plus(sweep().scale(prefixRows));
				}
				return total;
			}
			prefixRows *= childRows;
			mask |= child.producedMask();
			for (int f = 0; f < multiJoin.filters.length; f++) {
				if (ordered.filterDepth[f] == i) {
					total = total.plus(filter(multiJoin.filters[f].filter, prefixRows, mask));
				}
			}
		}
		for (int f = 0; f < multiJoin.filters.length; f++) {
			if (ordered.filterDepth[f] < 0 || ordered.filterDepth[f] >= ordered.order.length) {
				total = total.plus(filter(multiJoin.filters[f].filter, prefixRows, mask));
			}
		}
		return total;
	}

	private LmdbNativeCostVector filter(NativeBooleanFilter filter, double rows, long mask) {
		return perRow(Feature.INTERPRETED_ROW, rows).plus(witness(filter, rows, mask));
	}

	/** The access work an EXISTS witness in {@code filter} does over {@code rows} rows bound by {@code mask}. */
	private LmdbNativeCostVector witness(NativeBooleanFilter filter, double rows, long mask) {
		if (Double.isNaN(rows) && witnessOf(filter)) {
			// an unknown row count under a witness: the sweep ceiling, never a NaN factor
			return sweep();
		}
		if (filter instanceof RecordingNativeBooleanFilter recording) {
			return witness(recording.delegate, rows, mask);
		}
		if (filter instanceof NegatedNativeBooleanFilter negated) {
			return witness(negated.delegate, rows, mask);
		}
		if (filter instanceof BooleanCombinationFilter combination) {
			return witness(combination.left, rows, mask).plus(witness(combination.right, rows, mask));
		}
		if (filter instanceof StatementPatternExistsFilter exists) {
			PatternPlan pattern = new PatternPlan(exists.s, exists.p, exists.o, exists.c, exists.contexts,
					exists.namedContextScope, 1D);
			if (mode == Mode.KERNEL) {
				return kernelWitness(pattern, rows, mask);
			}
			// one probe per row (memoised on the varying slots; consecutive repeats are free), one record each
			return firstMatch(LmdbNativeCostVectors.pattern(pattern, row, mask)).scale(rows)
					.plus(perRow(Feature.MEMBERSHIP_TEST, rows));
		}
		if (filter instanceof ExistsFilter exists) {
			SlotPlan subPlan = exists.subPlan;
			if (mode == Mode.KERNEL && !hasIsland(subPlan)) {
				return kernelWitness(subPlan, rows, mask);
			}
			if (subPlan instanceof PatternPlan pattern && PatternMembershipProbe.tryCreate(pattern) != null) {
				return firstMatch(LmdbNativeCostVectors.pattern(pattern, row, mask)).scale(rows)
						.plus(perRow(Feature.MEMBERSHIP_TEST, rows));
			}
			if (memoReadMask(subPlan) >= 0L) {
				// the subplan's first match per distinct key, a memo lookup per row
				return firstMatchPlan(subPlan, mask).scale(rows).plus(perRow(Feature.MEMBERSHIP_TEST, rows));
			}
			return firstMatchPlan(subPlan, mask).scale(rows);
		}
		return LmdbNativeCostVector.zero();
	}

	private static boolean hasIsland(SlotPlan plan) {
		if (isIsland(plan)) {
			return true;
		}
		if (plan instanceof MultiJoinPlan multiJoin) {
			for (SlotPlan child : multiJoin.children) {
				if (hasIsland(child)) {
					return true;
				}
			}
			return false;
		}
		if (plan instanceof JoinPlan join) {
			return hasIsland(join.left) || hasIsland(join.right);
		}
		if (plan instanceof FilterPlan filter) {
			return hasIsland(filter.arg);
		}
		if (plan instanceof UnionPlan union) {
			return hasIsland(union.left) || hasIsland(union.right);
		}
		return plan instanceof MinusPlan || plan instanceof LeftJoinPlan;
	}

	/** A kernel witness: one seek per pattern of the body and one record per outer row, no structure around it. */
	private LmdbNativeCostVector kernelWitness(SlotPlan body, double rows, long mask) {
		int patterns = Math.max(1, patternCount(body));
		return perRow(Feature.INDEX_SEEK, multiply(rows, patterns)).plus(perRow(Feature.SCANNED_ROW, rows))
				.plus(perRow(Feature.DECODED_ROW, rows));
	}

	private static int patternCount(SlotPlan plan) {
		if (plan instanceof PatternPlan) {
			return 1;
		}
		if (plan instanceof MultiJoinPlan multiJoin) {
			int count = 0;
			for (SlotPlan child : multiJoin.children) {
				count += patternCount(child);
			}
			return count;
		}
		if (plan instanceof JoinPlan join) {
			return patternCount(join.left) + patternCount(join.right);
		}
		if (plan instanceof FilterPlan filter) {
			return patternCount(filter.arg);
		}
		if (plan instanceof UnionPlan union) {
			return patternCount(union.left) + patternCount(union.right);
		}
		if (plan instanceof LeftJoinPlan leftJoin) {
			return patternCount(leftJoin.left) + patternCount(leftJoin.right);
		}
		if (plan instanceof MinusPlan minus) {
			return patternCount(minus.left) + patternCount(minus.right);
		}
		return 1;
	}

	/** A pattern's access stopped at its first record. */
	private static LmdbNativeCostVector firstMatch(LmdbNativeCostVector access) {
		LmdbNativeCostVector.Builder builder = LmdbNativeCostVector.builder();
		for (Feature feature : Feature.values()) {
			double high = access.high(feature);
			if (high <= 0D) {
				continue;
			}
			if (feature == Feature.SCANNED_ROW || feature == Feature.DECODED_ROW) {
				builder.add(feature, Math.min(1D, access.low(feature)), Math.min(1D, access.expected(feature)),
						Math.min(1D, high));
			} else {
				builder.add(feature, access.low(feature), access.expected(feature), high);
			}
		}
		return builder.build();
	}

	/**
	 * A subplan opened and read to its first row: every pattern of a join is seeked once (a cursor open each), the rows
	 * before the first match are not enumerated; other shapes are priced in full.
	 */
	private LmdbNativeCostVector firstMatchPlan(SlotPlan plan, long mask) {
		if (plan instanceof PatternPlan pattern) {
			return firstMatch(LmdbNativeCostVectors.pattern(pattern, row, mask))
					.plus(LmdbNativeCostVector.point(Feature.BRANCH_OPEN, 1D));
		}
		if (plan instanceof FilterPlan filter) {
			return firstMatchPlan(filter.arg, mask).plus(LmdbNativeCostVector.point(Feature.INTERPRETED_ROW, 1D));
		}
		if (plan instanceof MultiJoinPlan multiJoin) {
			MultiJoinPlan.OrderedPlan ordered = multiJoin.derivedPlan(mask);
			if (ordered.order.length > 0 && !correlated(ordered.order[0], mask)) {
				// the chain starts from a child the probe key does not reach: its rows are enumerated until a later
				// child matches, so the probe pays the chain, not a first match (medical q9, 2026-11-03: the MINUS
				// body's range-filtered child ran first and the sequential path never finished)
				return price(plan, mask).plus(perRow(Feature.BRANCH_OPEN, patternCount(plan)));
			}
			LmdbNativeCostVector total = LmdbNativeCostVector.zero();
			long bound = mask;
			for (SlotPlan child : ordered.order) {
				total = total.plus(firstMatchPlan(child, bound));
				bound |= child.producedMask();
			}
			return total.plus(perRow(Feature.INTERPRETED_ROW, multiJoin.filters.length));
		}
		if (plan instanceof JoinPlan join) {
			return firstMatchPlan(join.left, mask).plus(firstMatchPlan(join.right, mask | join.left.producedMask()));
		}
		return price(plan, mask).plus(LmdbNativeCostVector.point(Feature.BRANCH_OPEN, 1D));
	}

	private LmdbNativeCostVector minus(MinusPlan minus, long mask) {
		LmdbNativeCostVector left = price(minus.left, mask);
		double leftRows = rows(minus.left, mask);
		if (Double.isNaN(leftRows)) {
			return left.plus(sweep());
		}
		SlotPlan right = minus.right;
		long correlatedMask = mask | (minus.left.producedMask() & minus.sharedMask);
		// the batch cursor is vectorised for a pattern right side; any other right side wraps the row cursor
		LmdbNativeCostVector conversion = mode == Mode.BATCH && !(right instanceof PatternPlan)
				? perRow(Feature.INTERPRETED_ROW, leftRows).plus(perRow(Feature.BATCH_ROW, leftRows))
				: LmdbNativeCostVector.zero();
		if (minus.sharedMask == 0L) {
			// nothing to correlate on: the right side is drained once
			return left.plus(price(right, mask)).plus(conversion);
		}
		if (mode == Mode.KERNEL && !hasIsland(right)) {
			return left.plus(kernelWitness(right, leftRows, correlatedMask));
		}
		if (right instanceof PatternPlan pattern && PatternMembershipProbe.tryCreate(pattern) != null) {
			// a single pattern: an existence probe per left row while the membership structure warms up
			return left.plus(firstMatch(LmdbNativeCostVectors.pattern(pattern, row, correlatedMask)).scale(leftRows))
					.plus(perRow(Feature.MEMBERSHIP_TEST, leftRows))
					.plus(conversion);
		}
		boolean assured = (minus.sharedMask & ~SlotPlan.assuredMask(right)) == 0L;
		LmdbNativeCostVector perProbe = assured
				// the right side binds every shared slot on every row: a correlated first match answers it
				? firstMatchPlan(right, correlatedMask)
				// the right side is evaluated independently and compared per row
				: price(right, mask).plus(LmdbNativeCostVector.point(Feature.BRANCH_OPEN, 1D));
		LmdbNativeCostVector memo = memoReadMask(right) >= 0L ? perRow(Feature.MEMBERSHIP_TEST, leftRows)
				: LmdbNativeCostVector.zero();
		return left.plus(perProbe.scale(leftRows)).plus(memo).plus(conversion);
	}

	private LmdbNativeCostVector leftJoin(LeftJoinPlan leftJoin, long mask) {
		LmdbNativeCostVector left = price(leftJoin.left, mask);
		double leftRows = rows(leftJoin.left, mask);
		if (Double.isNaN(leftRows)) {
			return left.plus(sweep());
		}
		SlotPlan right = leftJoin.right;
		long rightMask = mask | leftJoin.left.producedMask();
		// the batch cursor is vectorised for a pattern right side; any other right side wraps the row cursor
		LmdbNativeCostVector conversion = mode == Mode.BATCH && !(right instanceof PatternPlan)
				? perRow(Feature.INTERPRETED_ROW, leftRows).plus(perRow(Feature.BATCH_ROW, leftRows))
				: LmdbNativeCostVector.zero();
		if (leftJoin.lexicalSharedSlots != null || leftJoin.lexicalProblemSlots != null) {
			return left.plus(child(right, rightMask, leftRows)).plus(conversion);
		}
		boolean patternRight = right instanceof PatternPlan
				|| right instanceof FilterPlan filter && filter.arg instanceof PatternPlan;
		if (patternRight || mode == Mode.KERNEL) {
			// a payload probe (or the kernel's correlated probe) per left row
			return left.plus(price(right, rightMask).scale(leftRows)).plus(conversion);
		}
		long readMask = memoReadMask(right);
		if (readMask >= 0L && (readMask & leftJoin.left.producedMask()) != 0L && right.producedMask() != 0L) {
			// the fragment runs per key and its rows are replayed per left row
			double rightRows = rows(right, rightMask);
			return left.plus(price(right, rightMask).plus(LmdbNativeCostVector.point(Feature.BRANCH_OPEN, 1D))
					.scale(leftRows))
					.plus(perRow(Feature.DECODED_ROW, multiply(rightRows, leftRows)))
					.plus(conversion);
		}
		return left.plus(child(right, rightMask, leftRows)).plus(conversion);
	}

	private static double multiply(double rows, double factor) {
		return Double.isNaN(rows) ? Double.NaN : rows * factor;
	}
}
